<script setup lang="ts">
import { ref } from 'vue'
import UiButton from '@/components/ui/UiButton.vue'
import UiPageState from '@/components/ui/UiPageState.vue'
import UiNotice from '@/components/ui/UiNotice.vue'
import UiBadge from '@/components/ui/UiBadge.vue'
import OwnerPager from '@/components/owner/OwnerPager.vue'
import RemotePicker from '@/components/owner/RemotePicker.vue'
import PaymentDetailDialog from '@/components/billing/PaymentDetailDialog.vue'
import { eventPayload, useOwnerList } from '@/composables/useOwnerApi'
import { formatMoney } from '@/lib/format'
import { formatDateTime } from '@/lib/notifications'
import type { Payment } from '@/types/billing'
const success = ref('')
const method = ref(''), receiptState = ref(''), from = ref(''), until = ref(''), rooms = ref<number[]>([]), groups = ref<number[]>([]), pickerOpen = ref(false), paymentId = ref<number | null>(null)
const { items, loading, loadError, page, lastPage, total, load } = useOwnerList<Payment>('/payments')
function filter() { void load(1, { ...(method.value ? { payment_method: method.value } : {}), ...(receiptState.value ? { status: receiptState.value } : {}), ...(from.value ? { paid_from: eventPayload(from.value) } : {}), ...(until.value ? { paid_until: eventPayload(until.value) } : {}), ...(rooms.value[0] ? { room_id: rooms.value[0] } : {}), ...(groups.value[0] ? { rental_group_id: groups.value[0] } : {}) }); pickerOpen.value = false }
void load()
</script>
<template><section class="management-page"><RouterLink class="back-link" to="/owner/invoices">← Hóa đơn</RouterLink><header class="management-header"><div><span class="eyebrow">Tiền thực nhận</span><h1>Lịch sử thu tiền hóa đơn</h1><p>Đối chiếu từng lần thu bằng tiền mặt hoặc chuyển khoản.</p></div></header><UiNotice v-if="success" tone="success">{{ success }}</UiNotice><form class="management-toolbar" @submit.prevent="filter"><label>Từ thời điểm (giờ Việt Nam)<input v-model="from" type="datetime-local" step="1" class="ui-input" /></label><label>Đến thời điểm (giờ Việt Nam)<input v-model="until" type="datetime-local" step="1" class="ui-input" /></label><label>Hình thức<select v-model="method" class="ui-select"><option value="">Tất cả</option><option value="cash">Tiền mặt</option><option value="bank_transfer">Chuyển khoản</option></select></label><label>Trạng thái phiếu<select v-model="receiptState" class="ui-select"><option value="">Tất cả</option><option value="active">Có hiệu lực</option><option value="voided">Đã hủy ghi nhận</option></select></label><UiButton variant="secondary" @click="pickerOpen = !pickerOpen">Chọn phòng / nhóm</UiButton><UiButton type="submit" variant="secondary" :loading="loading">Lọc lần thu</UiButton><div v-if="pickerOpen" class="form-grid" style="width:100%"><RemotePicker v-model="rooms" label="Phòng" path="/rooms" label-key="room_number" /><RemotePicker v-model="groups" label="Nhóm thuê" path="/rental-groups" label-key="group_code" /></div></form><UiPageState v-if="loading" kind="loading" /><UiPageState v-else-if="loadError" kind="error" :description="loadError"><UiButton @click="load()">Thử lại</UiButton></UiPageState><UiPageState v-else-if="!items.length" title="Chưa có lần thu phù hợp" description="Tiền hóa đơn chỉ xuất hiện khi bạn xác nhận thực nhận tiền." /><div v-else class="management-grid"><article v-for="payment in items" :key="payment.id" class="record-card"><header><div><h2>{{ payment.receipt_number }} · Phòng {{ payment.room.room_number }}</h2><p class="help-text">{{ payment.invoice_number }}</p></div><strong>{{ formatMoney(payment.amount) }}</strong></header><UiBadge :tone="payment.status === 'voided' ? 'neutral' : 'success'">{{ payment.status === 'voided' ? 'Đã hủy ghi nhận' : 'Có hiệu lực' }}</UiBadge><p v-if="payment.replaces_payment_id" class="help-text">Thay thế PT-{{ payment.replaces_payment_id }}.</p><p v-if="payment.correction?.replacement_payment_id" class="help-text">Đã có phiếu thay thế PT-{{ payment.correction.replacement_payment_id }}.</p><dl class="record-facts"><div><dt>Nhận tiền lúc</dt><dd>{{ formatDateTime(payment.paid_at) }}</dd></div><div><dt>Hình thức</dt><dd>{{ payment.payment_method === 'cash' ? 'Tiền mặt' : 'Chuyển khoản' }}</dd></div></dl><footer><UiButton variant="secondary" :aria-label="`Chi tiết ${payment.receipt_number}`" @click="paymentId = payment.id">Chi tiết lần thu</UiButton><RouterLink class="record-link" :to="`/owner/invoices/${payment.invoice_id}`">Xem hóa đơn</RouterLink></footer></article></div><OwnerPager v-if="!loadError && total" :page="page" :last-page="lastPage" :total="total" :loading="loading" @change="load($event)" /><PaymentDetailDialog :payment-id="paymentId" @close="paymentId = null" @changed="success = 'Đã sửa sai phiếu thu. Phiếu gốc được giữ để đối chiếu.'; load()" /></section></template>
